WITH ValidPayments AS (SELECT * FROM payments WHERE method = 'bank_transfer' OR method IS NULL), payments_stats AS (SELECT method, CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'tier_1' ELSE 'other' END AS status_group, ROUND(STDDEV(amount), 2) AS stddev_amount FROM ValidPayments GROUP BY method, CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'tier_1' ELSE 'other' END) SELECT * FROM payments_stats ORDER BY stddev_amount DESC, status_group
